    bvlHowtoRows: [["— Slik bruker du kalkulatoren —","Sammenlign total kostnad ved å eie eller leie over tid"],["Kjøpspris","Hva boligen koster å kjøpe. Lånebeløpet er kjøpesummen minus egenkapitalen."],["Egenkapital","Det du betaler selv. Utlånsforskriften krever minst 10 %."],["Lånerente","Gjennomsnittlig rente over låneperioden. Bruk dagens rente hvis du er usikker."],["Månedlig leie","Hva en tilsvarende bolig vil koste å leie i dag."],["Felleskostnader","Månedlig felleskostnad for blokk eller sameie. Leiligheter har typisk 2 000–5 000 kr i måneden."],["Vedlikehold","Årlig vedlikehold som andel av boligverdien. Vanlig tommelfingerregel er 1 %."],["Tidsperiode","Hvor lenge vil du bo der? Kort tid gjør ofte leie best, lang tid gjør ofte eie best."],["Boligprisvekst","Forventet årlig vekst. Historisk snitt i Norge 1990–2024 er ca. 5 % per år, men det svinger."],["Leievekst","Forventet vekst i leieprisen. Ofte 2–4 % per år i storbyer."],["Avkastning på egenkapitalen","Hva egenkapitalen ville gitt i fond hvis du leide. Indeksfond har gitt ca. 6–7 % per år i snitt."],["— Slik leser du resultatene —",""],["Nettokostnad ved eie","Renter + felleskostnader + vedlikehold − skattefradrag − verdistigning. Avdrag teller ikke: det er dine egne penger."],["Nettokostnad ved leie","All husleie i perioden − det egenkapitalen og det du sparer hver måned (det eie koster mer enn leie) kunne tjent i fond."],["Eie lønner seg fra","Året eie blir billigere enn leie og holder seg billigere ut perioden."],["Formue ved eie","Boligverdi − gjenværende lån. Det du sitter igjen med."],["— Godt å vite —",""],["Kort horisont","Flytter du innen 5 år, taper eie ofte på dokumentavgift og megler. De er ikke med i tallene her."],["Lang horisont","Over 15–20 år vinner eie som regel, fordi verdistigningen rekker å veie opp for kostnadene."],["Usikker rente","Kjør kalkulatoren flere ganger med forskjellig rente — se hvor mye det spiller inn."]],
